#include <bits/stdc++.h>
using namespace std;

#define ll long long 

ll get_score(ll s , ll c1 , vector<ll>& p, ll n){
    return 2ll * p[c1] + p[2 * s - c1] + 3ll * p[3 * n - s - c1];
}

void solve() {
    ll n ;
    cin>> n ;
    
    vector<ll> a(3 * n);
    for(auto &it : a) cin>> it ;
    
    sort(a.rbegin(), a.rend());
    
    vector<ll> p(3 * n + 1 , 0);
    
    for(ll i = 0 ; i < 3 * n ; i++){
        p[i + 1] = p[i] + a[i] ;
    }
    
    ll mx = 0 ;
    
    for(ll i = 0 ; i <= n ; i++){
        ll low = 0 ;
        ll high = i ;
        
        while(high - low > 2 ){
            ll m1 = (low + (high - low) / 3);
            ll m2 = (high - (high - low) / 3);
            
            ll v1 = get_score(i, m1, p, n);
            ll v2 = get_score(i, m2, p, n) ;
            
            if(v1 < v2){
                
                low = m1 ;
            } else {
                high = m2 ;
            }
        }
        
        for(ll j = low ; j <= high ; j++){
            mx = max(mx, get_score(i, j, p, n));
        }
    }
    
    cout<< mx <<endl ;
}

int main() {
	// your code goes here
	
	int t ;
	cin>> t ;
	
	while(t--){
	    solve() ;
	}

}
